entries[400026] = { ["name"] = "Crimson Combatant's Medallion", ["text"] = "2 sec cast\nReagents:\nAwakened Ire (2), Serene Ink (3), Chilled Rune\nOptional Reagents:\nLesser Illustrious Insight (#92) , Blotting Sand (#249)\nVendor:\nKorganar Smolderforge\nZone:\nValdrakken\nCost:\n3\n\nCrimson Combatant's Medallion\nBinds when equipped\nUnique-Equipped: Gladiator's Medallions (1)Trinket\n+205 [Agility or Strength or Intellect] Use: Removes all movement impairing effects and all effects which cause loss of control of your character.\n70\n\nGladiator's Distinction (0/2)\nGladiator's Emblem\nGladiator's Medallion" }
entries[400027] = { ["name"] = "Crimson Combatant's Insignia of Alacrity", ["text"] = "2 sec cast\nReagents:\nAwakened Ire (2), Blazing Ink (3), Chilled Rune\nOptional Reagents:\nLesser Illustrious Insight (#92) , Blotting Sand (#249)\nVendor:\nKorganar Smolderforge\nZone:\nValdrakken\nCost:\n3\n\nCrimson Combatant's Insignia of Alacrity\nBinds when equipped\nUnique-EquippedTrinket\n+ 291 Haste\nEquip: Your spells and abilities have a chance to grant 457 primary stat for 20 sec.\n70\n\nGladiator's Distinction (0/2)\nGladiator's Emblem\nGladiator's Medallion" }
entries[400028] = { ["name"] = "Crimson Combatant's Emblem", ["text"] = "2 sec cast\nReagents:\nAwakened Ire (2), Flourishing Ink (3), Chilled Rune\nOptional Reagents:\nLesser Illustrious Insight (#92) , Blotting Sand (#249)\nVendor:\nKorganar Smolderforge\nZone:\nValdrakken\nCost:\n3\n\nCrimson Combatant's Emblem\nBinds when equipped\nUnique-EquippedTrinket\n+205 [Agility or Strength or Intellect] Use: Increases maximum health by 26226 for 15 sec. (2 Min Cooldown)\n70\n\nGladiator's Distinction (0/2)\nGladiator's Emblem\nGladiator's Medallion" }
